"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

export type InstallPromptProps = Omit<React.ComponentPropsWithoutRef<"section">, "title"> & {
  title?: React.ReactNode;
  description?: React.ReactNode;
  icon?: React.ReactNode;
  actionLabel?: string;
  dismissLabel?: string;
  installing?: boolean;
  onInstall: () => void;
  onDismiss?: () => void;
};

export function InstallPrompt({
  title = "Install this app",
  description = "Add it to your device for quicker access and a focused app window.",
  icon,
  actionLabel = "Install",
  dismissLabel = "Not now",
  installing = false,
  onInstall,
  onDismiss,
  className,
  ...props
}: InstallPromptProps) {
  const titleId = React.useId();
  const descriptionId = React.useId();

  return (
    <section
      data-slot="install-prompt"
      aria-labelledby={titleId}
      aria-describedby={descriptionId}
      className={cn("flex items-start gap-3 rounded-2xl border border-border/70 bg-background p-4 shadow-sm", className)}
      {...props}
    >
      {icon ? <div data-slot="install-prompt-icon" className="grid size-10 shrink-0 place-items-center rounded-xl bg-muted text-foreground [&>svg]:size-5">{icon}</div> : null}
      <div className="min-w-0 flex-1">
        <h2 id={titleId} className="text-sm font-semibold tracking-[-0.01em]">{title}</h2>
        <p id={descriptionId} className="mt-1 text-sm leading-5 text-muted-foreground">{description}</p>
        <div className="mt-3 flex flex-wrap items-center gap-2">
          <button type="button" disabled={installing} onClick={onInstall} className="inline-flex min-h-11 cursor-pointer items-center justify-center rounded-xl bg-primary px-4 text-sm font-semibold text-primary-foreground outline-none transition-[opacity,transform] duration-150 ease-out focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-55 motion-reduce:transition-none motion-reduce:active:scale-100">
            {installing ? "Opening…" : actionLabel}
          </button>
          {onDismiss ? <button type="button" disabled={installing} onClick={onDismiss} className="inline-flex min-h-11 cursor-pointer items-center justify-center rounded-xl px-4 text-sm font-medium text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-55 motion-reduce:transition-none">{dismissLabel}</button> : null}
        </div>
      </div>
    </section>
  );
}

"use client";

import * as React from "react";

export type InstallPromptOutcome = "accepted" | "dismissed";
export type InstallPromptResult = InstallPromptOutcome | "unavailable" | "error";
export type InstallPromptStatus =
  | "unknown"
  | "unavailable"
  | "available"
  | "prompting"
  | InstallPromptOutcome
  | "installed"
  | "error";

type NativeInstallPromptEvent = Event & {
  prompt: () => Promise<void>;
  userChoice: Promise<{ outcome: InstallPromptOutcome; platform: string }>;
};

function isInstalled() {
  const navigatorWithStandalone = window.navigator as Navigator & { standalone?: boolean };
  return Boolean(
    navigatorWithStandalone.standalone
    || window.matchMedia("(display-mode: standalone)").matches
    || window.matchMedia("(display-mode: fullscreen)").matches,
  );
}

export function useInstallPrompt() {
  const promptEventRef = React.useRef<NativeInstallPromptEvent | null>(null);
  const activePromptRef = React.useRef<Promise<InstallPromptResult> | null>(null);
  const mountedRef = React.useRef(false);
  const [status, setStatus] = React.useState<InstallPromptStatus>("unknown");
  const [error, setError] = React.useState<Error | null>(null);

  React.useEffect(() => {
    mountedRef.current = true;

    const handleBeforeInstallPrompt = (event: Event) => {
      event.preventDefault();
      promptEventRef.current = event as NativeInstallPromptEvent;
      setError(null);
      setStatus("available");
    };
    const handleInstalled = () => {
      promptEventRef.current = null;
      setError(null);
      setStatus("installed");
    };

    window.addEventListener("beforeinstallprompt", handleBeforeInstallPrompt);
    window.addEventListener("appinstalled", handleInstalled);
    setStatus(isInstalled() ? "installed" : "unavailable");

    return () => {
      mountedRef.current = false;
      window.removeEventListener("beforeinstallprompt", handleBeforeInstallPrompt);
      window.removeEventListener("appinstalled", handleInstalled);
    };
  }, []);

  const prompt = React.useCallback(() => {
    if (activePromptRef.current) return activePromptRef.current;

    const event = promptEventRef.current;
    if (!event) return Promise.resolve("unavailable" as const);

    promptEventRef.current = null;
    setError(null);
    setStatus("prompting");

    const activePrompt = (async () => {
      try {
        await event.prompt();
        const choice = await event.userChoice;
        if (mountedRef.current) setStatus(choice.outcome);
        return choice.outcome;
      } catch (cause) {
        const nextError = cause instanceof Error ? cause : new Error("The install prompt could not be opened.");
        if (mountedRef.current) {
          setError(nextError);
          setStatus("error");
        }
        return "error" as const;
      } finally {
        activePromptRef.current = null;
      }
    })();

    activePromptRef.current = activePrompt;
    return activePrompt;
  }, []);

  return {
    status,
    error,
    canPrompt: status === "available",
    isInstalled: status === "installed",
    prompt,
  };
}
